import { Sankey } from '@dreadnought/ui/react';
const nodes = [{ id: 'a', label: 'Поиск' }, { id: 'b', label: 'Сайт' }];
const links = [{ id: 'ab', source: 'a', target: 'b', value: 70 }];
export function Example() { return <Sankey label="Переходы" nodes={nodes} links={links} />; }

import { Sankey, useSankey } from '@dreadnought/ui/react';
const nodes = [{id:'a',label:'Сайт'},{id:'b',label:'Заказ'}]; const links = [{id:'ab',source:'a',target:'b',value:60}];
function Controls() { const {page} = useSankey(); return <button disabled={page.page === page.count} onClick={() => page.change(page.page + 1)}>Следующая страница</button>; }
export function Example() { return <Sankey label="Данные" nodes={nodes} links={links} pageSize={1}><Controls /><Sankey.Plot tooltipContent={({defaultContent}) => <div>{defaultContent}</div>}>{({defaultContent}) => defaultContent}</Sankey.Plot><Sankey.Table /><Sankey.Pagination /><Sankey.Empty /></Sankey>; }
